+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * The filters applied to a customer query.
+ *
+ * <p>Name terms are matched independently against the first and last name. A
+ * term can occur in either field, and every term must match. Normalizing both
+ * sides makes the match insensitive to case and accents.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+
+        String[] terms = nameTerms();
+        if (terms.length == 0) {
+            return true;
+        }
+
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return Arrays.stream(terms)
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** Returns whether the name portion narrows the result set. */
+    public boolean hasNameTerms() {
+        return nameTerms().length > 0;
+    }
+
+    private String[] nameTerms() {
+        String trimmed = name.strip();
+        if (trimmed.isEmpty()) {
+            return new String[0];
+        }
+        return Arrays.stream(trimmed.split("(?U)\\s+"))
+                .map(CustomerFilter::normalize)
+                .filter(term -> !term.isEmpty())
+                .toArray(String[]::new);
+    }
+
+    private static String normalize(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
